.dm-lva{display:flex;flex-direction:column;gap:14px}
.dm-lva-q{display:flex;justify-content:flex-end}
.dm-lva-a{display:flex;flex-direction:column;gap:14px;min-height:230px}
/* on a card the first answer keeps the room its sources and follow-ups fill, so nothing climbs when they arrive */
.dm-stage-in>.dm-lva .dm-lva-a{min-height:324px}
.dm-lva-turn{display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-lva-th{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13.5px;color:var(--dm-muted)}
.dm-lva-tb{display:inline-flex;gap:6px;align-self:flex-start;padding:2px var(--dm-s-2);margin-left:-8px;border-radius:var(--dm-r-pill);transition:color var(--dm-t-fast),background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-lva-tb:hover{color:var(--dm-fg2);background:var(--dm-row)}}
.dm-lva-tb>.dm-i{transition:transform .2s var(--dm-ease)}
.dm-lva-tb[aria-expanded="true"]>.dm-i{transform:rotate(180deg)}
.dm-lva-tlist{list-style:none;margin:0;padding:2px 0 2px var(--dm-s-3);border-left:1px solid color-mix(in srgb,var(--dm-rail) 50%,transparent);display:flex;flex-direction:column;gap:var(--dm-s-1);font-size:13px;color:var(--dm-muted)}
.dm-lva-p{margin:0;font-size:14px;line-height:1.65}
.dm-lva-p .dm-w{display:inline;animation:dm-lvw .5s var(--dm-ease) both}
@keyframes dm-lvw{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.dm-cite{display:inline-grid;place-items:center;min-width:17px;height:17px;padding:0 var(--dm-s-1);margin:0 2px;border-radius:5px;background:var(--dm-hover);font-size:10.5px;font-weight:500;color:var(--dm-fg2);vertical-align:2px;cursor:default;transition:background .2s,color .2s}
.dm-cite.dm-on{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
@media (hover:hover) and (pointer:fine){.dm-cite:hover{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}}
.dm-lva-p .dm-cite{animation:dm-lvw .5s var(--dm-ease) both}
.dm-lva-src{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--dm-muted)}
.dm-lva-sb{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:28px;padding:0 9px 0 5px;border-radius:var(--dm-r-pill);color:var(--dm-fg2);transition:background .2s,color .2s}
.dm-lva-sb[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.dm-lva-sb:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-lva-sb>.dm-i{color:var(--dm-muted);transition:transform .35s var(--dm-ease)}
.dm-lva-sb[aria-expanded="true"]>.dm-i{transform:rotate(180deg)}
.dm-lva-fav{display:flex}
.dm-lva-fav span{width:18px;height:18px;border-radius:5px;display:grid;place-items:center;font-size:9.5px;font-weight:500;color:#fff;background-image:linear-gradient(rgba(0,0,0,.3),rgba(0,0,0,.3));margin-left:-4px;box-shadow:0 0 0 1.5px var(--dm-surface);transition:margin .3s var(--dm-ease)}
.dm-lva-fav span:first-child{margin-left:0}
@media (hover:hover) and (pointer:fine){.dm-lva-sb:hover .dm-lva-fav span:not(:first-child){margin-left:2px}}
.dm-lva-acts{display:flex;gap:2px;margin-left:-6px}
.dm-lva-acts .dm-ib{width:28px;height:28px}
.dm-lva-ll{display:flex;flex-direction:column;gap:2px}
.dm-lva-s{display:flex;align-items:center;gap:10px;width:100%;padding:7px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk));font-size:13px;text-align:left;color:var(--dm-fg);transition:background .2s}
.dm-lva-s.dm-on{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-lva-s:hover{background:var(--dm-row)}}
.dm-lva-s .dm-n{width:17px;height:17px;border-radius:5px;background:var(--dm-hover);display:grid;place-items:center;font-size:10.5px;font-weight:500;color:var(--dm-fg2);flex:none;transition:background .2s,color .2s}
.dm-lva-s.dm-on .dm-n{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
@media (hover:hover) and (pointer:fine){.dm-lva-s:hover .dm-n{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}}
.dm-lva-s .dm-d{color:var(--dm-muted);font-size:12px;margin-right:auto;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-lva-s>.dm-i{color:var(--dm-muted);opacity:0;transition:opacity .2s}
@media (hover:hover) and (pointer:fine){.dm-lva-s:hover>.dm-i{opacity:1}}
.dm-lva-fu{display:flex;flex-direction:column;align-items:flex-start;gap:6px}
.dm-lva-fu button{display:inline-flex;align-items:center;gap:var(--dm-s-2);padding:6px var(--dm-s-3) 6px 10px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px;color:var(--dm-fg2);transition:color .2s,box-shadow .2s,transform .2s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-lva-fu button:hover{color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent)}}
